import { CONFIG } from './config.js';
import { createStore, freshState, allocate, allocationFeedback, STAGES } from './state.js';
import { escapeHTML as esc, button, orbit, chapter, progress, giftArt, cake, toast, dialog, scope } from './ui.js';
import { createEffects } from './effects.js';
import { createSound } from './sound.js';
import { mountGame } from './games.js';
import { mountWishInput } from './wish.js';

const app=document.querySelector('#app');
document.title=CONFIG.title;
for(const [key,value] of Object.entries(CONFIG.theme)) document.documentElement.style.setProperty(`--${key}`,value);
let effects;try{effects=createEffects()}catch{effects={burst(){},bright(){},reduced:true}}
const syncSound=state=>{const musicButton=document.querySelector('#sound'),effectsButton=document.querySelector('#sfx');musicButton.setAttribute('aria-pressed',String(state.music));musicButton.querySelector('span').textContent=state.loading?'准备音乐':state.music?'音乐开':'音乐关';musicButton.disabled=state.loading;musicButton.setAttribute('aria-label',state.music?'关闭生日背景音乐':'播放生日背景音乐');effectsButton.setAttribute('aria-pressed',String(state.effects));effectsButton.querySelector('span').textContent=state.effects?'音效开':'音效关';effectsButton.setAttribute('aria-label',state.effects?'关闭互动音效':'开启互动音效');document.querySelector('#music-status').textContent=state.music?'正在播放：祝你生日快乐 · 轻柔伴奏':'';};
const sound=createSound(toast,syncSound);
let storage;try{storage=window.localStorage}catch{storage={getItem(){throw Error()},setItem(){throw Error()},removeItem(){throw Error()}}}
const store=createStore(storage,text=>setTimeout(()=>toast(text),600));
let state=store.load(),life=scope(),cakeClicks=0,busy=false;
const save=()=>store.save(state);
const on=(selector,handler)=>{const el=app.querySelector(selector);if(el)el.addEventListener('click',handler,{signal:life.signal})};
const go=stage=>{state.stage=stage;save();render();window.scrollTo({top:0,behavior:'instant'});app.focus({preventScroll:true})};
const complete=index=>{if(!state.completed.includes(index)){state.completed.push(index);save()}};
function frame(step,content){app.innerHTML=`<section class="scene">${progress(step)}${content}</section>`}
function render(){life.stop();life=scope();busy=false;document.querySelector('#blackout').style.opacity='0';document.body.classList.toggle('final-scene',['cake','letter'].includes(state.stage));effects.bright(state.stage==='letter'||state.stage==='cake'&&state.candle!=='unlit');
  const stages={intro:renderIntro,identity:renderIdentity,upgrade:renderUpgrade,allocation:renderAllocation,tasks:renderTasks,stars:renderGame,hunt:renderGame,reaction:renderGame,energy:renderEnergy,gifts:renderGifts,cake:renderCake,letter:renderLetter};
  try{(stages[state.stage]||renderIntro)()}catch{app.innerHTML=`<section class="scene recovery">${chapter(0,'星光稍稍走了个神。','刚刚好像发生了一点小意外，再试一次吧。')}<div class="actions">${button('retry','recover')}${button('continue','recover-next','','secondary')}</div></section>`;on('#recover',render);on('#recover-next',()=>{if(['stars','hunt','reaction'].includes(state.stage)){complete(['stars','hunt','reaction'].indexOf(state.stage));go(STAGES[STAGES.indexOf(state.stage)+1])}else if(state.stage==='cake'){state.candle='out';go('letter')}else go(STAGES[Math.min(STAGES.indexOf(state.stage)+1,STAGES.length-1)])})}
}
function renderIntro(){app.innerHTML=`<section class="scene intro-grid"><div class="intro-copy"><p class="eyebrow">一场专属旅程 · 即将开启</p><h1>平凡的宇宙里，<br>有一天<em>只属于你。</em></h1><p class="subtext">有一份小小的心意，穿过星光，<br>正在等你亲手打开。</p><div class="intro-log" aria-live="polite"><p id="intro-previous"></p><p id="intro-current"></p></div>${button('enter','enter','hidden')}<button id="speed-intro" class="text-button">轻点屏幕，加快星光的脚步</button><p class="hint intro-footnote">给自己留几分钟，慢慢拆开这份心意。</p></div>${orbit()}</section>`;
  let line=0,char=0,waiting=0,done=false;
  const current=app.querySelector('#intro-current'),previous=app.querySelector('#intro-previous');
  function finish(){done=true;previous.textContent=CONFIG.intro.at(-2);current.textContent=CONFIG.intro.at(-1);app.querySelector('#enter').hidden=false;app.querySelector('#speed-intro').hidden=true}
  if(effects.reduced)finish();else life.every(()=>{if(done||document.hidden)return;if(waiting>0){waiting--;return}const text=CONFIG.intro[line];current.textContent=text.slice(0,++char);if(char>=text.length){if(line===CONFIG.intro.length-1){finish();return}previous.textContent=text;line++;char=0;waiting=7}},45);
  app.addEventListener('click',e=>{if(!e.target.closest('#enter'))finish()},{signal:life.signal});on('#enter',()=>go('identity'));
}
function renderIdentity(){frame(0,`<div class="identity-layout"><div>${chapter(1,'检测到一位<br><em>特别用户。</em>','正在确认身份……')}<p class="subtext">如果你正在看这个页面，<br>那么大概率没有找错人。</p><div class="actions">${button('identity','identity')}</div><p class="hint" style="margin-top:22px">身份验证依据：今天值得被好好祝福。</p></div><div class="identity-card"><div class="card-seal" aria-hidden="true">✦</div><p class="eyebrow">今日限定 · 专属席位</p><h3 class="serif">${esc(CONFIG.friend)}</h3><div class="identity-divider"></div><p>这一天，你是故事的主角。</p><span class="card-stamp">特别邀请</span></div></div>`);on('#identity',()=>{if(busy)return;busy=true;app.querySelector('#identity').disabled=true;toast('身份确认完成。今日主角已成功登录。');sound.play();life.after(()=>go('upgrade'),1000)})}
function renderUpgrade(){const statuses=[['快乐值','正在提升'],['好运值','正在提升'],['财富值','正在努力加载'],['烦恼值','正在清理'],['熬夜次数','建议适当减少'],['可爱程度','系统拒绝继续计算'],['未来可能性','无法估量']];frame(1,`<div class="upgrade-layout"><div>${chapter(2,'新的一岁，<br><em>正式开启。</em>','年龄等级提升完成。<br>恭喜你成功进入新的一岁。')}<div class="upgrade-emblem" aria-hidden="true"><span>✦</span><i>新一岁</i></div></div><div class="status-panel"><p class="panel-label">正在为你更新生活的小参数</p>${statuses.map(([name,value],i)=>`<div class="status-row" style="--delay:${i*.16}s"><span>${name}</span><span>${value}${i<2?'<i class="rise" aria-hidden="true"> ↗</i>':''}</span></div>`).join('')}<div class="actions">${button('upgrade','allocate')}</div></div></div>`);on('#allocate',()=>go('allocation'))}
function renderAllocation(){
  frame(1,`${chapter(2,'生日的祝福，<em>不用做选择。</em>','快乐、健康、好运……每一项都可以拉满。拖动星轨，为新的一岁加一点偏爱。')}<div class="allocation-layout"><div class="attribute-grid">${CONFIG.attributes.map((name,i)=>`<div class="attribute"><div class="attribute-label"><label for="attribute-${i}">${esc(name)}</label><output id="value-${i}" for="attribute-${i}">${state.attributes[i]}</output></div><div class="attribute-controls"><button class="stepper" data-index="${i}" data-delta="-5" aria-label="减少${esc(name)}祝福点数">−</button><input type="range" min="0" max="${CONFIG.points}" step="1" value="${state.attributes[i]}" id="attribute-${i}" data-index="${i}" aria-valuetext="${state.attributes[i]}点"><button class="stepper" data-index="${i}" data-delta="5" aria-label="增加${esc(name)}祝福点数">＋</button></div></div>`).join('')}</div><aside class="allocation-summary"><span class="mini-star" aria-hidden="true">✧</span><p>已经满格的祝福</p><strong id="points-left"></strong><p class="hint" id="point-hint"></p><div class="point-meter"><i id="point-meter-fill"></i></div>${button('balance','balance','','secondary')}${button('allocation','confirm-points')}${button('clear','clear-points','','text-button')}</aside></div>`);
  const update=()=>{
    const full=state.attributes.filter(n=>n===CONFIG.points).length;
    app.querySelector('#points-left').textContent=`${full} ／ ${CONFIG.attributes.length}`;
    app.querySelector('#point-meter-fill').style.width=`${state.attributes.reduce((a,b)=>a+b,0)/(CONFIG.points*CONFIG.attributes.length)*100}%`;
    app.querySelector('#point-hint').textContent=full===CONFIG.attributes.length?'每一项都满格。所有美好，你都值得。':'祝福不设总额度，每一项都能拥有一百分。';
    app.querySelectorAll('input[type="range"]').forEach((input,i)=>{input.value=state.attributes[i];input.style.setProperty('--fill',`${state.attributes[i]/CONFIG.points*100}%`);input.setAttribute('aria-valuetext',`${state.attributes[i]}点`);app.querySelector(`#value-${i}`).textContent=state.attributes[i]});
    app.querySelectorAll('.stepper').forEach(el=>{el.disabled=Number(el.dataset.delta)<0?state.attributes[el.dataset.index]===0:state.attributes[el.dataset.index]===CONFIG.points});save();
  };
  app.querySelectorAll('input[type="range"]').forEach(el=>el.addEventListener('input',()=>{state.attributes=allocate(state.attributes,Number(el.dataset.index),el.value);update()},{signal:life.signal}));
  app.querySelectorAll('.stepper').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.index);state.attributes=allocate(state.attributes,i,state.attributes[i]+Number(el.dataset.delta));update()});
  on('#balance',()=>{state.attributes=CONFIG.attributes.map(()=>CONFIG.points);update();sound.celebrate();effects.burst(innerWidth*.7,innerHeight*.5);toast('快乐、健康、好运……这次，每一项都拉满。')});
  on('#clear-points',()=>{state.attributes=CONFIG.attributes.map(()=>0);update()});
  on('#confirm-points',()=>dialog('你的新一岁，已确认。',allocationFeedback(state.attributes).map(text=>`<p>${esc(text)}</p>`).join(''),{confirm:CONFIG.buttons.continue,onConfirm:()=>go('tasks')}));update();
}
function renderTasks(){frame(2,`${chapter(3,'新的旅程，已经开始。','不过，在领取今天真正的礼物之前，还需要完成几个小任务。')}<div class="task-cards">${[['✦','接住生日星星','移动星篮，接住十二颗流星'],['☾','寻找隐藏礼物','拨开云朵，发现藏好的惊喜'],['✧','蓄光挑战','按住蓄光，在亮起时松手']].map(([icon,title,desc],i)=>`<article class="task-card"><span class="task-number">第${['一','二','三'][i]}站</span><div class="task-icon" aria-hidden="true">${icon}</div><h3>${title}</h3><p>${desc}</p></article>`).join('')}</div><div class="actions centered">${button('tasks','accept')}</div><p class="hint centered">没有排名，也没有输赢。今天只负责开心就好。</p>`);on('#accept',()=>go('stars'))}
function renderGame(){frame(2,'<div id="game"></div>');const root=app.querySelector('#game');mountGame(state.stage,root,state,save,complete,effects,sound,life);root.addEventListener('game-next',()=>go({stars:'hunt',hunt:'reaction',reaction:'energy'}[state.stage]),{signal:life.signal})}
function renderEnergy(){frame(2,`<div class="energy-scene">${chapter(3,'你收集的光，<em>都在这里。</em>','正在汇总今天获得的生日能量……')}<div class="energy-orb" aria-hidden="true"><span>✦</span><i></i><b></b></div><h3 id="energy-message">三份星光，正在汇合。</h3><p class="subtext centered">接下来，有一些美好想交到你手里。</p><div class="actions centered">${button('gifts','open-gifts')}</div></div>`);life.after(()=>{app.querySelector('#energy-message').textContent='生日能量已满。';sound.play(784)},effects.reduced?0:1200);on('#open-gifts',()=>go('gifts'))}
function renderGifts(){frame(3,`${chapter(4,'有些美好，<em>想亲手送给你。</em>','星光已经替你系好了丝带。轻轻点开，看看里面藏着什么。')}<div class="gift-grid">${CONFIG.gifts.map((g,i)=>`<button class="gift-card ${state.gifts.includes(i)?'is-open':''} ${i===4?'is-locked':''}" data-gift="${i}" aria-label="${i===4?'尚未解锁的最后一份礼物':state.gifts.includes(i)?`重读礼物：${esc(g.title)}`:`打开第${['一','二','三','四'][i]}份礼物`}"><span class="gift-index">第${['一','二','三','四','五'][i]}份心意</span>${giftArt(i,state.gifts.includes(i))}<span class="gift-title">${i===4?'最后一份礼物':state.gifts.includes(i)?esc(g.title):'一份未知的美好'}</span><span class="gift-caption">${i===4?'等一个特别的时刻':state.gifts.includes(i)?'已收下 · 可以再次打开':'轻点，拆开丝带'}</span></button>`).join('')}</div><p class="gift-progress" id="gift-progress">已经收下 ${state.gifts.filter(n=>n<4).length} ／ 四份心意</p><div class="actions centered">${button('finale','to-cake',state.gifts.filter(n=>n<4).length<4?'disabled':'')}</div><p class="hint centered">最后一份礼物，留给蜡烛熄灭之后。</p>`);
  app.querySelectorAll('[data-gift]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.gift);if(i===4){toast('最后一份礼物似乎还没有解锁。它在生日场景里等你。');return}if(!state.gifts.includes(i)){state.gifts.push(i);save();sound.play(523+i*70);const r=el.getBoundingClientRect();effects.burst(r.x+r.width/2,r.y+r.height/2);el.classList.add('is-open');el.querySelector('.gift-art').classList.add('opened');el.querySelector('.gift-title').textContent=CONFIG.gifts[i].title;el.querySelector('.gift-caption').textContent='已收下 · 可以再次打开';el.setAttribute('aria-label',`重读礼物：${CONFIG.gifts[i].title}`);app.querySelector('#gift-progress').textContent=`已经收下 ${state.gifts.filter(n=>n<4).length} ／ 四份心意`;app.querySelector('#to-cake').disabled=state.gifts.filter(n=>n<4).length<4}dialog(CONFIG.gifts[i].title,`<div class="dialog-gift">${giftArt(i,true)}</div><p>${esc(CONFIG.gifts[i].content)}</p>`)});on('#to-cake',()=>{if(state.gifts.filter(n=>n<4).length===4)go('cake')})}
function cakeEgg(){cakeClicks++;if(cakeClicks===5){state.eggs=[...new Set([...state.eggs,'cake'])];save();toast(CONFIG.eggs.cake[0]);life.after(()=>{toast(CONFIG.eggs.cake[1]);effects.burst(innerWidth/2,innerHeight*.45,true);sound.celebrate()},1500)}}
function renderCake(){frame(4,`<div class="finale-layout"><div class="finale-art">${cake(state.candle==='lit'||state.candle==='hidden')}<p class="cake-caption">今夜的星光，都为你亮着。</p></div><div class="finale-copy" id="candle-content"></div></div>`);on('#cake-art',cakeEgg);renderCandleContent()}
function renderCandleContent(){const content=app.querySelector('#candle-content');if(state.candle==='unlit'){content.innerHTML=`${chapter(5,'接下来，<br><em>只需要许个愿。</em>','走到这里，今天的任务已经全部完成了。')}<p class="subtext">接下来，就做一件生日应该做的事情吧。</p><div class="actions">${button('light','light')}</div>`;on('#light',()=>{if(busy)return;busy=true;state.candle='lit';save();app.querySelector('#cake-art').classList.add('lit');effects.bright(true);sound.play(659);app.querySelector('#light').disabled=true;life.after(()=>{busy=false;renderCandleContent()},effects.reduced?0:1400)})}
  else if(state.candle==='lit'){content.innerHTML=`${chapter(5,'现在，可以许一个愿望。','把心里最柔软的期待，交给这一小片星空。')}<form id="wish-form"><label class="wish-label" for="wish">你的愿望</label><div class="wish-field-wrap"><textarea id="wish" class="private-wish" rows="3" maxlength="500" inputmode="text" lang="zh-CN" placeholder="悄悄写下你的中文愿望。" autocomplete="off" spellcheck="false" aria-describedby="wish-privacy wish-count"></textarea><span id="wish-mask" aria-hidden="true"></span></div><p id="wish-count" class="hint" role="status">文字会被遮住，保存后可以由你亲手打开。</p><p id="wish-privacy" class="hint">这个愿望只留在你的设备里，我不会知道。</p><p class="hint">也可以不写，在心里悄悄许愿。</p><div class="actions">${button('wish','hide-wish','type="submit"')}</div></form>`;
    const field=app.querySelector('#wish');const wishInput=mountWishInput(field,app.querySelector('#wish-count'),app.querySelector('#wish-mask'),life.signal);field.addEventListener('focus',()=>life.after(()=>field.scrollIntoView({block:'center',behavior:effects.reduced?'instant':'smooth'}),250),{signal:life.signal});app.querySelector('#wish-form').addEventListener('submit',e=>{e.preventDefault();if(busy)return;if(wishInput.composing){toast('先选好输入法里的文字，再把愿望藏起来。');return}busy=true;const wish=wishInput.read();const stored=wish?store.saveWish(wish):true;wishInput.clear();field.blur();state.candle='hidden';save();content.classList.add('wish-vanish');const star=document.createElement('span');star.className='wish-flight';star.textContent='✦';star.setAttribute('aria-hidden','true');app.querySelector('.finale-layout').append(star);effects.burst(innerWidth*.65,innerHeight*.45);life.after(()=>{star.remove();content.classList.remove('wish-vanish');busy=false;renderCandleContent();if(!stored){app.querySelector('#wish-saved-message').textContent='愿望已在此刻许下。这里无法保存它，请把它留在心里。';toast('这个设备暂时无法保存愿望，我们没有把它发送到任何地方。')}},effects.reduced?0:1100)},{signal:life.signal})}
  else if(state.candle==='hidden'){content.innerHTML=`${chapter(5,'愿望已经藏好了。','希望有一天，它真的会实现。')}<p class="subtext" id="wish-saved-message">准备好之后，就把蜡烛吹灭吧。</p><div class="actions">${button('blow','blow')}${button('viewWish','view-wish','','text-button')}</div><p class="hint">轻点就好，不需要麦克风。</p>`;on('#view-wish',showWish);on('#blow',()=>{if(busy)return;busy=true;void sound.startBirthday();app.querySelector('#blow').disabled=true;app.querySelector('#cake-art').classList.add('blowing');sound.play(392);life.after(()=>{state.candle='out';save();app.querySelector('#cake-art').classList.remove('lit');app.querySelector('#cake-art').classList.add('smoking');effects.bright(false);life.after(()=>{document.querySelector('#blackout').style.opacity='1'},effects.reduced?0:850);life.after(()=>{if(!state.gifts.includes(4))state.gifts.push(4);go('letter');effects.burst(innerWidth/2,innerHeight*.4,true);sound.celebrate();life.after(()=>effects.burst(innerWidth*.25,innerHeight*.3,true),500)},effects.reduced?100:1950)},effects.reduced?0:850)})}
  else {if(!state.gifts.includes(4))state.gifts.push(4);go('letter')}
}
function showWish(){const wish=store.readWish();dialog('这是你留给未来的悄悄话。',wish?`<p class="wish-reveal">${esc(wish)}</p><p class="hint">只有点开时才会显示。关闭后，再替你藏好。</p>`:'<p>这里还没有写下的愿望。也许那天，你把它留在了心里。</p>');}
function renderLetter(){frame(4,`<div class="letter-scene"><p class="eyebrow centered">最后一份礼物 · 终于来到你手里</p><p class="birthday-english" lang="en">Happy Birthday to You</p><h2>${esc(CONFIG.friend)}，愿新的一岁，<em>有光，有自由。</em></h2><article class="letter"><div class="letter-top"><span>致 ${esc(CONFIG.friend)}</span><span aria-hidden="true">✧</span></div><div class="letter-body">${CONFIG.blessing.slice(0,3).map((text,i)=>`<p class="letter-line" style="--delay:${effects.reduced?0:i*.9}s">${esc(text)}</p>`).join('')}<div id="letter-rest" hidden>${CONFIG.blessing.slice(3).map(text=>`<p>${esc(text)}</p>`).join('')}</div><p id="letter-fold-hint" class="hint">还有一些话，等你亲手展开。</p></div><div class="letter-signature"><span>把所有美好，都送给你</span><span aria-hidden="true">✦</span></div></article><div class="actions centered">${button('show','show-letter','aria-expanded="false" aria-controls="letter-rest"','secondary')}</div><div class="letter-bottom">${cake(false)}<p>这份心意，随时都可以回来看看。</p><button class="secret-star" id="secret-star" aria-label="角落里的一颗小星星">✧</button></div><div class="privacy-actions">${button('viewWish','view-wish','','text-button')}${button('forget','forget-wish','','text-button')}<span id="wish-deleted" class="hint" role="status"></span></div></div>`);on('#cake-art',cakeEgg);on('#show-letter',()=>{const rest=app.querySelector('#letter-rest');const expanded=rest.hidden;rest.hidden=!expanded;app.querySelector('#letter-fold-hint').hidden=expanded;app.querySelectorAll('.letter-line').forEach(el=>{el.style.animation='none';el.style.opacity='1'});const toggle=app.querySelector('#show-letter');toggle.textContent=expanded?'收起信件':CONFIG.buttons.show;toggle.setAttribute('aria-expanded',String(expanded));if(expanded){app.querySelector('#secret-star').classList.add('awake');rest.scrollIntoView({block:'center',behavior:effects.reduced?'instant':'smooth'})}});life.after(()=>{app.querySelector('#secret-star')?.classList.add('awake')},effects.reduced?0:CONFIG.blessing.length*1800);on('#secret-star',()=>{state.eggs=[...new Set([...state.eggs,'star'])];save();effects.burst(innerWidth*.7,innerHeight*.5,true);dialog(CONFIG.eggs.star[0],CONFIG.eggs.star.slice(1).map((line,i)=>`<p class="${i===1?'egg-quote':''}">${esc(line)}</p>`).join(''))});on('#view-wish',showWish);on('#forget-wish',()=>dialog('把这个愿望交还给你。','<p>将删除当前设备保存的愿望，生日旅程和祝福都会保留。</p>',{confirm:CONFIG.buttons.forget,cancel:CONFIG.buttons.cancel,onConfirm:()=>{const ok=store.forgetWish();app.querySelector('#wish-deleted').textContent=ok?'本地愿望已删除。':'这里暂时无法删除，请稍后再试。'}}));
}
document.querySelector('#sound').onclick=()=>sound.toggle();
document.querySelector('#sfx').onclick=()=>sound.toggleEffects();
syncSound(sound.status());
document.querySelector('#restart').onclick=()=>dialog('再走一次这段星光旅程？','<p>将清除当前设备上的旅程进度和愿望，从第一束星光重新开始。</p>',{confirm:CONFIG.buttons.restart,cancel:CONFIG.buttons.cancel,onConfirm:()=>{const ok=store.reset();state=freshState();cakeClicks=0;go('intro');if(!ok)toast('本次旅程已重新开始；旧的本地记录可能仍然保留。')}});
window.addEventListener('error',()=>{toast('刚刚好像发生了一点小意外，再试一次吧。')});window.addEventListener('unhandledrejection',()=>toast('星光稍稍走了个神，仍然可以继续这段旅程。'));
render();
if(state.stage!=='intro')setTimeout(()=>toast('欢迎回来，已经替你留住上次的星光。'),400);

// 接口只提供章节和属性配置，不读取或返回愿望。
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};
  register({name:'read_birthday_progress',title:'查看生日旅程',description:'读取当前章节、已收集的能量和礼物数量，不读取愿望。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({chapter:['序章','身份确认','新一岁升级','属性分配','生日任务','抓住星星','寻找礼物','反应挑战','能量汇总','生日礼物','生日许愿','最终祝福'][STAGES.indexOf(state.stage)],energy:state.completed.length,gifts:state.gifts.length})});
  register({name:'configure_birthday_blessings',title:'分配新一岁祝福',description:'只在属性分配章节中调整祝福点数；不会替用户确认或跳过章节。',inputSchema:{type:'object',properties:{points:{type:'array',items:{type:'integer',minimum:0,maximum:100},minItems:CONFIG.attributes.length,maxItems:CONFIG.attributes.length}},required:['points'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(state.stage!=='allocation')throw new Error('请先进入属性分配章节。');const v=input?.points;if(!Array.isArray(v)||v.length!==CONFIG.attributes.length||v.some(n=>!Number.isInteger(n)||n<0||n>CONFIG.points))throw new Error('祝福点数需要是每项不超过一百的非负整数。');state.attributes=[...v];save();render();return{full:v.filter(n=>n===CONFIG.points).length}}});
}
